  [LogLevel.WARN]: 'WARN',
  [LogLevel.ERROR]: 'ERROR',
  [LogLevel.FATAL]: 'FATAL',
};

function parseLogLevel(envValue: string | undefined): LogLevel | null {
  if (!envValue) return null;
  const upper = envValue.toUpperCase();
  for (const [key, val] of Object.entries(LogLevel)) {
    if (key === upper && typeof val === 'number') {
